return $input.all().map(item => {
  const m = item.json;
  const remitente = m.from?.value?.[0]?.address?.trim().toLowerCase() || '';
  const destinatario = m.to?.value?.[0]?.address?.trim().toLowerCase() || '';
  const mensaje = (m.text || '').trim();

  return {
    json: {
      gmailId: m.id || '',
      threadId: m.threadId || '',
      remitente,
      nombreRemitente: m.from?.value?.[0]?.name || '',
      asunto: m.subject || '',
      mensaje,
      fecha: m.date || '',
      datosValidos: Boolean(m.id && m.threadId && remitente && mensaje && remitente !== destinatario),
      estadoInicial: 'Nueva'
    }
  };
});

const consulta = $('Preparar consulta y validar datos').first().json;

const articulos = $input.all()
  .map(item => item.json.fields ?? item.json)
  .filter(a => a['Título'] && a['Estado de vigencia'] === 'Vigente')
  .map(a => ({
    titulo: a['Título'],
    equipo: a['Tipo de equipo'] ?? '',
    sintoma: a['Síntoma'] ?? '',
        respuesta: Object.entries(a).find(([clave]) => clave.startsWith('Solución'))?.[1] ?? ''
  }));

return [{
  json: {
    ...consulta,
    conocimiento: articulos,
    cantidadArticulos: articulos.length
  }
}];

